-- no BCrypt check accepts, so nobody can log in until the backend sets
-- real hashes (fail-closed). See README 'Demo accounts'.
-- =====================================================================
SET DEFINE OFF






-- Demo accounts. password_hash is a placeholder until the backend sets real BCrypt hashes.

